# Expected values are SymPy's outputs for the same calls (Permutations and permutation groups).

skip_on_cran()

.bt <- new.env(parent = asNamespace("symcompR"))
eval(parse(text = r"---(# Python str() of R results, for the battery
pyset <- function(x) structure(x, pyset = TRUE)
L <- function(x) structure(x, pylist = TRUE)
TP <- function(...) structure(list(...), pytuple = TRUE)
srt <- function(ps) {
  if (!length(ps)) return(ps)
  m <- do.call(rbind, lapply(ps, `[[`, "array"))
  ps[do.call(order, as.data.frame(m))]
}
af <- function(ps) lapply(ps, function(p) L(p$array))
.pynum <- function(v) {
  if (inherits(v, "bigz")) return(as.character(v))
  if (is.logical(v)) return(if (v) "True" else "False")
  if (is.character(v)) return(paste0("'", v, "'"))
  if (is.na(v)) return("None")
  if (v == round(v) && abs(v) < 1e15) return(format(v, scientific = FALSE))
  format(v, digits = 17)
}
.pystr <- function(x, top = TRUE) {
  if (is.null(x)) return("None")
  if (inherits(x, "Permutation")) return(.perm_str(x, repr = !top))
  if (inherits(x, "Cycle")) return(.cycle_str(x, repr = !top))
  if (inherits(x, c("PermutationGroup", "Coset", "SymmetricPermutationGroup", "GroupHomomorphism"))) return(format(x))
  if (inherits(x, "symmatrix")) {
    rows <- vapply(seq_len(x$nrow), function(i) paste0("[", paste(vapply(x$data[(i - 1L) * x$ncol + seq_len(x$ncol)], .str, ""), collapse = ", "), "]"), "")
    return(paste0("Matrix([", paste(rows, collapse = ", "), "])"))
  }
  if (inherits(x, "sym")) return(gsub("**", "^", sstr(x), fixed = TRUE))
  elems <- function(x) {
    if (inherits(x, "bigz")) return(vapply(seq_along(x), function(i) as.character(x[i]), ""))
    if (is.list(x)) return(vapply(x, .pystr, "", top = FALSE))
    vapply(seq_along(x), function(i) .pynum(x[[i]]), "")
  }
  if (isTRUE(attr(x, "pyset"))) {
    e <- elems(x)
    return(if (!length(e)) "set()" else paste0("{", paste(e, collapse = ", "), "}"))
  }
  if (isTRUE(attr(x, "pytuple"))) {
    e <- elems(x)
    return(if (length(e) == 1L) paste0("(", e, ",)") else paste0("(", paste(e, collapse = ", "), ")"))
  }
  pl <- isTRUE(attr(x, "pylist"))
  if (is.atomic(x) && !is.null(names(x)) && !pl) {
    e <- elems(unname(x))
    return(paste0("{", paste(paste0(names(x), ": ", e), collapse = ", "), "}"))
  }
  if (is.list(x) && length(x) && !is.null(names(x)) && !pl) {
    e <- elems(unname(x))
    return(paste0("{", paste(paste0(names(x), ": ", e), collapse = ", "), "}"))
  }
  if (is.character(x) && length(x) == 1L && !pl) return(if (top) x else paste0("'", x, "'"))
  if ((is.atomic(x) || inherits(x, "bigz")) && length(x) == 1L && !pl) return(.pynum(if (inherits(x, "bigz")) x else x[[1L]]))
  paste0("[", paste(elems(x), collapse = ", "), "]")
}

TETRA <- function() PermutationGroup(lapply(list(c(0, 2, 3, 1), c(1, 2, 0, 3), c(3, 1, 0, 2), c(3, 0, 2, 1), c(1, 0, 3, 2), c(2, 3, 0, 1), c(3, 2, 1, 0)), Permutation))
CUBE <- function() PermutationGroup(lapply(list(c(1, 2, 3, 0, 5, 6, 7, 4), c(4, 0, 3, 7, 5, 1, 2, 6), c(4, 5, 1, 0, 7, 6, 2, 3), c(1, 0, 4, 5, 2, 3, 7, 6), c(6, 2, 1, 5, 7, 3, 0, 4), c(6, 7, 3, 2, 5, 4, 0, 1), c(3, 7, 4, 0, 2, 6, 5, 1), c(4, 7, 6, 5, 0, 3, 2, 1), c(6, 5, 4, 7, 2, 1, 0, 3), c(0, 3, 7, 4, 1, 2, 6, 5), c(5, 1, 0, 4, 6, 2, 3, 7), c(5, 6, 2, 1, 4, 7, 3, 0), c(7, 4, 0, 3, 6, 5, 1, 2)), Permutation))
# sympy/combinatorics/testutil.py
.verify_bsgs <- function(group, base, gens) {
  sgd <- .distribute_gens_by_base(base, gens)
  cur <- group
  for (i in seq_along(base)) {
    cand <- PermutationGroup(sgd[[i]])
    if (group_order(cur) != group_order(cand)) return(FALSE)
    cur <- stabilizer(cur, base[i])
  }
  group_order(cur) == 1
}
.naive_centralizer <- function(G, other) {
  if (inherits(other, "Permutation")) other <- PermutationGroup(list(other))
  gens <- lapply(other$gens, `[[`, "array")
  Filter(function(e) all(vapply(gens, function(g) .af_commutes_with(e, g), TRUE)), generate_dimino(G, af = TRUE))
}
.verify_centralizer <- function(G, arg, centr = NULL) {
  if (is.null(centr)) centr <- centralizer(G, arg)
  a <- vapply(generate_dimino(centr, af = TRUE), paste, "", collapse = ",")
  b <- vapply(.naive_centralizer(G, arg), paste, "", collapse = ",")
  setequal(a, b)
}
.verify_normal_closure <- function(G, arg, closure = NULL) {
  if (is.null(closure)) closure <- normal_closure(G, arg)
  sub <- if (inherits(arg, "PermutationGroup")) arg$gens else if (inherits(arg, "Permutation")) list(arg) else arg
  conj <- list()
  for (el in generate_dimino(G)) for (gen in sub) conj[[length(conj) + 1L]] <- gen ^ el
  conj <- conj[!duplicated(.pkeys(conj))]
  is_subgroup(closure, PermutationGroup(conj))
}
)---"), envir = .bt)
.run <- function(code) {
  e <- new.env(parent = .bt)
  get(".py_seed", envir = .bt)(0)
  gsub("\n", " ", get(".pystr", envir = .bt)(eval(parse(text = code), envir = e)), fixed = TRUE)
}
.setup <- function(code) invisible(eval(parse(text = code), envir = .bt))
.err <- function(code) tryCatch({ .run(code); "no error" }, error = function(e) gsub("\n", " ", conditionMessage(e), fixed = TRUE))

test_that("Permutations and permutation groups match SymPy", {
  expect_equal(.run("Permutation(c(0, 1, 2, 3))"), "(3)")
  expect_equal(.run("p <- Permutation(c(0,1,2,3)); L(vapply(0:3, function(i) perm_call(p, i), 0L))"), "[0, 1, 2, 3]")
  expect_equal(.run("L(array_form(perm_call(Permutation(c(0,1,2,3)), 1, 2)))"), "[0, 2, 1, 3]")
  expect_equal(.err("perm_call(Permutation(c(0,1,2,3)), -1)"), "-1 should be an integer between 0 and 3")
  expect_equal(.err("perm_call(Permutation(c(0,1,2,3)), 5)"), "5 should be an integer between 0 and 3")
  expect_equal(.err("perm_call(Permutation(c(0,1,2,3)), 4)"), "4 should be an integer between 0 and 3")
  expect_equal(.run("L(perm_call(Permutation(c(0,1,2,3)), 0:3))"), "[0, 1, 2, 3]")
  expect_equal(.run("Permutation(size = 4)"), "(3)")
  expect_equal(.run("Permutation(size = 4) == Permutation(3)"), "True")
  expect_equal(.run("Permutation(Permutation(3), size = 5)"), "(4)")
  expect_equal(.run("Permutation(list(c(1, 2)), size = 4)"), "(3)(1 2)")
  expect_equal(.run("Permutation(list(c(1, 2), 0, 3))"), "(3)(1 2)")
  expect_equal(.run("L(perm_support(Permutation(c(2, 5, 1, 6, 3, 0, 4))))"), "[0, 1, 2, 3, 4, 5, 6]")
  expect_equal(.run("L(perm_support(Permutation(c(2, 5, 1, 6, 3, 0, 4))))"), "[0, 1, 2, 3, 4, 5, 6]")
  expect_equal(.run("L(perm_support(Permutation(list(1, c(0, 3, 5, 6, 2, 4)))))"), "[0, 2, 3, 4, 5, 6]")
  expect_equal(.run("Permutation(list(1, c(0, 3, 5, 6, 2, 4)))"), "(0 3 5 6 2 4)")
  expect_equal(.run("L(array_form(Permutation(list(1, c(0, 3, 5, 6, 2, 4)))))"), "[3, 1, 4, 5, 0, 6, 2]")
  expect_equal(.run("lapply(cyclic_form(Permutation(c(2, 5, 1, 6, 3, 0, 4))), L)"), "[[0, 2, 1, 5], [3, 6, 4]]")
  expect_equal(.run("lapply(full_cyclic_form(Permutation(list(1, c(0, 3, 5, 6, 2, 4)))), L)"), "[[0, 3, 5, 6, 2, 4], [1]]")
  expect_equal(.run("perm_cardinality(Permutation(c(2, 5, 1, 6, 3, 0, 4)))"), "5040")
  expect_equal(.run("perm_cycles(Permutation(list(1, c(0, 3, 5, 6, 2, 4))))"), "2")
  expect_equal(.run("perm_rmul(Permutation(list(1, c(0, 3, 5, 6, 2, 4))), Permutation(c(2, 5, 1, 6, 3, 0, 4)))"), "(0 4 5 3 2 1 6)")
  expect_equal(.run("perm_rmul(Permutation(c(2, 5, 1, 6, 3, 0, 4)), Permutation(list(1, c(0, 3, 5, 6, 2, 4))))"), "(0 6 1 5 4 2 3)")
  expect_equal(.run("lapply(cyclic_form(perm_rmul(Permutation(list(c(1, 2, 3), c(0, 4))), Permutation(list(c(1, 2, 4), 0, 3)))), L)"), "[[0, 4, 2], [1, 3]]")
  expect_equal(.run("perm_rmul(Permutation(c(2, 5, 1, 6, 3, 0, 4)), Permutation(list(1, c(0, 3, 5, 6, 2, 4))), Permutation(c(1, 3, 2, 0, 4, 6, 5)))"), "(0 5 1)(2 3 6 4)")
  expect_equal(.run("lapply(cyclic_form(Permutation(c(0, 3, 1, 2))), L)"), "[[1, 3, 2]]")
  expect_equal(.run("perm_order(Permutation(c(0, 3, 1, 2)))"), "3")
  expect_equal(.run("lapply(perm_transpositions(Permutation(c(2, 5, 1, 6, 3, 0, 4))), function(t) do.call(TP, as.list(t)))"), "[(0, 5), (0, 1), (0, 2), (3, 4), (3, 6)]")
  expect_equal(.run("lapply(perm_transpositions(Permutation(c(1, 0))), function(t) do.call(TP, as.list(t)))"), "[(0, 1)]")
  expect_equal(.run("Permutation(c(2, 5, 1, 6, 3, 0, 4))^13"), "(0 2 1 5)(3 6 4)")
  expect_equal(.run("Permutation(list(1, c(0, 3, 5, 6, 2, 4)))^0"), "(6)")
  expect_equal(.run("Permutation(list(1, c(0, 3, 5, 6, 2, 4)))^-2"), "(0 2 5)(3 4 6)")
  expect_equal(.run("Permutation(list(1, c(0, 3, 5, 6, 2, 4)))^2"), "(0 5 2)(3 6 4)")
  expect_equal(.run("q <- Permutation(list(1, c(0, 3, 5, 6, 2, 4))); q^3 == q^2 * q"), "True")
  expect_equal(.run("perm_inverse(Permutation(1, 3))"), "(1 3)")
  expect_equal(.run("Permutation(1, 3) * Permutation(2, 0, 3)^-1"), "(0 2 3 1)")
  expect_equal(.run("perm_call(Permutation(0, 5, 3, 1, 6), 2, 4)"), "(0 5 3 1 6)(2 4)")
  expect_equal(.run("perm_rank(perm_call(Permutation(0, 5, 3, 1, 6), 2, 4))"), "4305")
  expect_equal(.run("Permutation(c(2, 5, 1, 6, 3, 0, 4)) + perm_rank(Permutation(list(1, c(0, 3, 5, 6, 2, 4))))"), "(0 5 3 1 6)(2 4)")
  expect_equal(.run("perm_rank(Permutation(c(2, 5, 1, 6, 3, 0, 4)) + perm_rank(Permutation(list(1, c(0, 3, 5, 6, 2, 4)))))"), "4305")
  expect_equal(.run("Permutation(c(2, 5, 1, 6, 3, 0, 4)) - perm_rank(Permutation(list(1, c(0, 3, 5, 6, 2, 4))))"), "(0 6 3 1 2 5 4)")
  expect_equal(.run("Permutation(list(1, c(0, 3, 5, 6, 2, 4))) - perm_rank(Permutation(c(2, 5, 1, 6, 3, 0, 4)))"), "(1 4 6 2)(3 5)")
  expect_equal(.err("Permutation(c(2, 5, 1, 6, 3, 0, 4)) + Permutation(0:9)"), "unsupported operand type(s) for +: 'int' and 'Permutation'")
  expect_equal(.run("Permutation(c(2, 5, 1, 6, 3, 0, 4)) * Permutation(integer())"), "(0 2 1 5)(3 6 4)")
  expect_equal(.run("Permutation(integer()) * Permutation(c(2, 5, 1, 6, 3, 0, 4))"), "(0 2 1 5)(3 6 4)")
  expect_equal(.run("Permutation(c(2, 5, 1, 6, 3, 0, 4)) * Permutation(list(c(0, 1)))"), "(0 2)(1 5)(3 6 4)")
  expect_equal(.run("Permutation(list(c(0, 1))) * Permutation(c(2, 5, 1, 6, 3, 0, 4))"), "(0 5)(1 2)(3 6 4)")
  expect_equal(.run("Permutation(c(2, 5, 1, 6, 3, 0, 4)) ^ Permutation(list(1, c(0, 3, 5, 6, 2, 4)))"), "(0 5 2)(1 6 3 4)")
  expect_equal(.run("Permutation(list(1, c(0, 3, 5, 6, 2, 4))) ^ Permutation(c(2, 5, 1, 6, 3, 0, 4))"), "(0 4 1 3 2 6)")
  expect_equal(.err("Permutation(c(2, 5, 1, 6, 3, 0, 4)) ^ Permutation(integer())"), "The permutations must be of equal size.")
  expect_equal(.run("3 ^ Permutation(c(2, 5, 1, 6, 3, 0, 4))"), "6")
  expect_equal(.run("perm_commutator(Permutation(c(2, 5, 1, 6, 3, 0, 4)), Permutation(list(1, c(0, 3, 5, 6, 2, 4))))"), "(0 1 3 4 6 5 2)")
  expect_equal(.run("perm_commutator(Permutation(list(1, c(0, 3, 5, 6, 2, 4))), Permutation(c(2, 5, 1, 6, 3, 0, 4)))"), "(0 2 5 6 4 3 1)")
  expect_equal(.err("perm_commutator(Permutation(c(2, 5, 1, 6, 3, 0, 4)), Permutation(integer()))"), "The permutations must be of equal size.")
  expect_equal(.run("L(perm_atoms(Permutation(list(1, c(0, 3, 5, 6, 2, 4)))))"), "[0, 1, 2, 3, 4, 5, 6]")
  expect_equal(.run("L(perm_inversion_vector(Permutation(c(2, 5, 1, 6, 3, 0, 4))))"), "[2, 4, 1, 3, 1, 0]")
  expect_equal(.run("L(perm_inversion_vector(Permutation(list(1, c(0, 3, 5, 6, 2, 4)))))"), "[3, 1, 2, 2, 0, 1]")
  expect_equal(.run("perm_from_inversion_vector(c(2, 4, 1, 3, 1, 0))"), "(0 2 1 5)(3 6 4)")
  expect_equal(.err("perm_from_inversion_vector(c(0, 2))"), "The inversion vector is not valid.")
  expect_equal(.run("perm_inversions(Permutation(500:0))"), "125250")
  expect_equal(.run("perm_parity(Permutation(c(0, 4, 1, 3, 2)))"), "0")
  expect_equal(.run("perm_parity(Permutation(c(0, 1, 4, 3, 2)))"), "1")
  expect_equal(.run(".af_parity(c(0L, 4L, 1L, 3L, 2L))"), "0")
  expect_equal(.run("perm_is_odd(Permutation(c(0, 4, 1, 3, 2)))"), "False")
  expect_equal(.run("perm_is_even(Permutation(c(0, 4, 1, 3, 2)))"), "True")
  expect_equal(.run("perm_is_singleton(Permutation(0))"), "True")
  expect_equal(.run("perm_is_empty(Permutation(integer()))"), "True")
  expect_equal(.run("perm_is_identity(Permutation(c(3, 2, 1, 0))^2)"), "True")
  expect_equal(.run("perm_inverse(Permutation(c(2, 5, 1, 6, 3, 0, 4)))^13"), "(0 5 1 2)(3 4 6)")
  expect_equal(.run("perm_max(Permutation(c(2, 5, 1, 6, 3, 0, 4)))"), "6")
  expect_equal(.run("perm_min(Permutation(c(2, 5, 1, 6, 3, 0, 4)))"), "0")
  expect_equal(.run("perm_max(Permutation(list(6, 5, 0:4)))"), "4")
  expect_equal(.run("perm_min(Permutation(list(6, 5, 0:4)))"), "0")
  expect_equal(.run("L(perm_ascents(Permutation(c(1, 5, 2, 0, 3, 6, 4))))"), "[0, 3, 4]")
  expect_equal(.run("L(perm_ascents(Permutation(list(c(1, 2, 3, 5, 6), c(0, 4)))))"), "[1, 2, 4]")
  expect_equal(.run("L(perm_ascents(Permutation(c(3, 2, 1, 0))))"), "[]")
  expect_equal(.run("L(perm_descents(Permutation(c(1, 5, 2, 0, 3, 6, 4))))"), "[1, 2, 5]")
  expect_equal(.run("L(perm_descents(Permutation(list(c(1, 2, 3, 5, 6), c(0, 4)))))"), "[0, 3, 5]")
  expect_equal(.run("perm_inversions(Permutation(c(1, 5, 2, 0, 3, 6, 4)))"), "7")
  expect_equal(.run("perm_inversions(Permutation(c(1, 5, 2, 0, 3, 6, 4, 7:135)))"), "7")
  expect_equal(.run("perm_signature(Permutation(c(1, 5, 2, 0, 3, 6, 4)))"), "-1")
  expect_equal(.run("perm_inversions(Permutation(list(c(1, 2, 3, 5, 6), c(0, 4))))"), "11")
  expect_equal(.run("perm_signature(Permutation(list(c(1, 2, 3, 5, 6), c(0, 4))))"), "-1")
  expect_equal(.run("perm_order(Permutation(c(1, 5, 2, 0, 3, 6, 4)))"), "6")
  expect_equal(.run("perm_order(Permutation(list(c(1, 2, 3, 5, 6), c(0, 4))))"), "10")
  expect_equal(.run("perm_length(Permutation(c(1, 5, 2, 0, 3, 6, 4)))"), "6")
  expect_equal(.run("perm_length(Permutation(list(c(1, 2, 3, 5, 6), c(0, 4))))"), "7")
  expect_equal(.run("perm_length(Permutation(c(3, 2, 1, 0)))"), "4")
  expect_equal(.run("lapply(perm_runs(Permutation(c(1, 5, 2, 0, 3, 6, 4))), L)"), "[[1, 5], [2], [0, 3, 6], [4]]")
  expect_equal(.run("lapply(perm_runs(Permutation(list(c(1, 2, 3, 5, 6), c(0, 4)))), L)"), "[[4], [2, 3, 5], [0, 6], [1]]")
  expect_equal(.run("lapply(perm_runs(Permutation(c(3, 2, 1, 0))), L)"), "[[3], [2], [1], [0]]")
  expect_equal(.run("perm_index(Permutation(c(1, 5, 2, 0, 3, 6, 4)))"), "8")
  expect_equal(.run("perm_index(Permutation(list(c(1, 2, 3, 5, 6), c(0, 4))))"), "8")
  expect_equal(.run("perm_index(Permutation(c(3, 2, 1, 0)))"), "3")
  expect_equal(.run("perm_precedence_distance(Permutation(c(1, 5, 2, 0, 3, 6, 4)), Permutation(list(c(1, 2, 3, 5, 6), c(0, 4))))"), "14")
  expect_equal(.run("perm_adjacency_distance(Permutation(c(1, 5, 2, 0, 3, 6, 4)), Permutation(list(c(1, 2, 3, 5, 6), c(0, 4))))"), "6")
  expect_equal(.run("perm_positional_distance(Permutation(c(1, 5, 2, 0, 3, 6, 4)), Permutation(list(c(1, 2, 3, 5, 6), c(0, 4))))"), "18")
  expect_equal(.run("perm_precedence_distance(Permutation(0:3), Permutation(3:0))"), "6")
