  expect_equal(.run("perm_josephus(4, 5, 2)"), "(0 3)(1 2 4)")
  expect_equal(.run("perm_adjacency_distance(Permutation(c(0, 3, 1, 2, 4)), perm_josephus(4, 5, 2))"), "3")
  expect_equal(.err("perm_adjacency_distance(Permutation(c(0, 3, 1, 2, 4)), Permutation(integer()))"), "The permutations must be of the same size.")
